    try {
      kept = JSON.parse(settingsStorage?.getItem(OWNERS_SEARCH_BY_KEPT) ?? "null");
    } catch {
      kept = null;
    }
    return typeof kept === "number" && [0, 1, 2, 3].includes(kept) ? kept : 0;
